    internal InnerCodeSecurityIntegrationUpdateGitHubIntegrationDetailFactory githubFactory { get; set; }

    protected override Humidifier.InspectorV2.CodeSecurityIntegrationTypes.UpdateDetails Create()
    {
        var updateDetailsResult = CreateUpdateDetails();
        factoryAction?.Invoke(updateDetailsResult);

        return updateDetailsResult;
    }

    private Humidifier.InspectorV2.CodeSecurityIntegrationTypes.UpdateDetails CreateUpdateDetails()
    {
        var updateDetailsResult = new Humidifier.InspectorV2.CodeSecurityIntegrationTypes.UpdateDetails();

        return updateDetailsResult;
    }
    public override void CreateChildren(Humidifier.InspectorV2.CodeSecurityIntegrationTypes.UpdateDetails result)
    {
        base.CreateChildren(result);

        result.gitlabSelfManaged ??= gitlabSelfManagedFactory?.Build();
        result.github ??= githubFactory?.Build();
    }

} // End Of Class

